\set ON_ERROR_STOP on
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT extensions.no_plan();
CREATE TEMP TABLE handoff_vectors AS SELECT $vectors${"qualification":"synthetic metadata only; not an installed or qualified backend","protocol_artifact":{"version":1,"input_projection":{"sha256":"1111111111111111111111111111111111111111111111111111111111111111","schema_version":1},"m1_mapping":{"sha256":"2222222222222222222222222222222222222222222222222222222222222222","schema_version":2},"m2_codec":{"sha256":"3333333333333333333333333333333333333333333333333333333333333333","schema_version":2},"transfer_validator":{"sha256":"4444444444444444444444444444444444444444444444444444444444444444","schema_version":1},"deadline_protocol":{"sha256":"5555555555555555555555555555555555555555555555555555555555555555","schema_version":1},"response_codec":{"sha256":"6666666666666666666666666666666666666666666666666666666666666666","schema_version":2}},"protocol_canonical":"{\"deadline_protocol\":{\"schema_version\":1,\"sha256\":\"5555555555555555555555555555555555555555555555555555555555555555\"},\"input_projection\":{\"schema_version\":1,\"sha256\":\"1111111111111111111111111111111111111111111111111111111111111111\"},\"m1_mapping\":{\"schema_version\":2,\"sha256\":\"2222222222222222222222222222222222222222222222222222222222222222\"},\"m2_codec\":{\"schema_version\":2,\"sha256\":\"3333333333333333333333333333333333333333333333333333333333333333\"},\"response_codec\":{\"schema_version\":2,\"sha256\":\"6666666666666666666666666666666666666666666666666666666666666666\"},\"transfer_validator\":{\"schema_version\":1,\"sha256\":\"4444444444444444444444444444444444444444444444444444444444444444\"},\"version\":1}","protocol_digest":"b4c50d2dda319599a9e9968582e077d52c0cf8b391799d10724aa1dce1f3dc53","valid":[{"name":"all_supported_types","profile":{"version":1,"generation":"10000000-0000-4000-8000-000000000001","source_backend_generation":"10000000-0000-4000-8000-000000000002","source_backend_config_digest":"7777777777777777777777777777777777777777777777777777777777777777","destination_backend_generation":"10000000-0000-4000-8000-000000000003","destination_backend_config_digest":"8888888888888888888888888888888888888888888888888888888888888888","protocol_artifact_digest":"b4c50d2dda319599a9e9968582e077d52c0cf8b391799d10724aa1dce1f3dc53","copy_adapter_digest":"9999999999999999999999999999999999999999999999999999999999999999","verification_adapter_digest":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","cohort_limits":{"max_ordinals":8,"max_unique_objects":10,"max_unique_bytes":28625792,"content_type_pairs":[{"kind":"image","source_content_type":"image/jpeg","prepared_content_type":"image/jpeg"},{"kind":"image","source_content_type":"image/png","prepared_content_type":"image/png"},{"kind":"image","source_content_type":"image/webp","prepared_content_type":"image/webp"},{"kind":"image","source_content_type":"image/heic","prepared_content_type":"image/heic"},{"kind":"image","source_content_type":"image/heif","prepared_content_type":"image/heif"},{"kind":"audio","source_content_type":"audio/wav","prepared_content_type":"audio/wav"},{"kind":"video","source_content_type":"video/mp4","prepared_content_type":null}],"alias_policy":"same_ordinal_exact_bytes_only","video_policy":"source_only"},"phase_ms":{"admission":10000,"copy":25000,"verification_claim":5000,"verification":15000,"verification_settlement":5000,"transfer":5000,"reconciliation":10000,"protocol_margin":5000},"total_ms":80000,"execution_model":"sequential_whole_cohort"},"profile_canonical":"{\"cohort_limits\":{\"alias_policy\":\"same_ordinal_exact_bytes_only\",\"content_type_pairs\":[{\"kind\":\"image\",\"prepared_content_type\":\"image/jpeg\",\"source_content_type\":\"image/jpeg\"},{\"kind\":\"image\",\"prepared_content_type\":\"image/png\",\"source_content_type\":\"image/png\"},{\"kind\":\"image\",\"prepared_content_type\":\"image/webp\",\"source_content_type\":\"image/webp\"},{\"kind\":\"image\",\"prepared_content_type\":\"image/heic\",\"source_content_type\":\"image/heic\"},{\"kind\":\"image\",\"prepared_content_type\":\"image/heif\",\"source_content_type\":\"image/heif\"},{\"kind\":\"audio\",\"prepared_content_type\":\"audio/wav\",\"source_content_type\":\"audio/wav\"},{\"kind\":\"video\",\"prepared_content_type\":null,\"source_content_type\":\"video/mp4\"}],\"max_ordinals\":8,\"max_unique_bytes\":28625792,\"max_unique_objects\":10,\"video_policy\":\"source_only\"},\"copy_adapter_digest\":\"9999999999999999999999999999999999999999999999999999999999999999\",\"destination_backend_config_digest\":\"8888888888888888888888888888888888888888888888888888888888888888\",\"destination_backend_generation\":\"10000000-0000-4000-8000-000000000003\",\"execution_model\":\"sequential_whole_cohort\",\"generation\":\"10000000-0000-4000-8000-000000000001\",\"phase_ms\":{\"admission\":10000,\"copy\":25000,\"protocol_margin\":5000,\"reconciliation\":10000,\"transfer\":5000,\"verification\":15000,\"verification_claim\":5000,\"verification_settlement\":5000},\"protocol_artifact_digest\":\"b4c50d2dda319599a9e9968582e077d52c0cf8b391799d10724aa1dce1f3dc53\",\"source_backend_config_digest\":\"7777777777777777777777777777777777777777777777777777777777777777\",\"source_backend_generation\":\"10000000-0000-4000-8000-000000000002\",\"total_ms\":80000,\"verification_adapter_digest\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\",\"version\":1}","profile_digest":"cc989b9af6cd020c4de42370fd1a1adf5caa37a972bbf1ed424f64806c5fb593"},{"name":"audio_only","profile":{"version":1,"generation":"10000000-0000-4000-8000-000000000001","source_backend_generation":"10000000-0000-4000-8000-000000000002","source_backend_config_digest":"7777777777777777777777777777777777777777777777777777777777777777","destination_backend_generation":"10000000-0000-4000-8000-000000000003","destination_backend_config_digest":"8888888888888888888888888888888888888888888888888888888888888888","protocol_artifact_digest":"b4c50d2dda319599a9e9968582e077d52c0cf8b391799d10724aa1dce1f3dc53","copy_adapter_digest":"9999999999999999999999999999999999999999999999999999999999999999","verification_adapter_digest":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","cohort_limits":{"max_ordinals":8,"max_unique_objects":10,"max_unique_bytes":28625792,"content_type_pairs":[{"kind":"audio","source_content_type":"audio/wav","prepared_content_type":"audio/wav"}],"alias_policy":"same_ordinal_exact_bytes_only","video_policy":"source_only"},"phase_ms":{"admission":10000,"copy":25000,"verification_claim":5000,"verification":15000,"verification_settlement":5000,"transfer":5000,"reconciliation":10000,"protocol_margin":5000},"total_ms":80000,"execution_model":"sequential_whole_cohort"},"profile_canonical":"{\"cohort_limits\":{\"alias_policy\":\"same_ordinal_exact_bytes_only\",\"content_type_pairs\":[{\"kind\":\"audio\",\"prepared_content_type\":\"audio/wav\",\"source_content_type\":\"audio/wav\"}],\"max_ordinals\":8,\"max_unique_bytes\":28625792,\"max_unique_objects\":10,\"video_policy\":\"source_only\"},\"copy_adapter_digest\":\"9999999999999999999999999999999999999999999999999999999999999999\",\"destination_backend_config_digest\":\"8888888888888888888888888888888888888888888888888888888888888888\",\"destination_backend_generation\":\"10000000-0000-4000-8000-000000000003\",\"execution_model\":\"sequential_whole_cohort\",\"generation\":\"10000000-0000-4000-8000-000000000001\",\"phase_ms\":{\"admission\":10000,\"copy\":25000,\"protocol_margin\":5000,\"reconciliation\":10000,\"transfer\":5000,\"verification\":15000,\"verification_claim\":5000,\"verification_settlement\":5000},\"protocol_artifact_digest\":\"b4c50d2dda319599a9e9968582e077d52c0cf8b391799d10724aa1dce1f3dc53\",\"source_backend_config_digest\":\"7777777777777777777777777777777777777777777777777777777777777777\",\"source_backend_generation\":\"10000000-0000-4000-8000-000000000002\",\"total_ms\":80000,\"verification_adapter_digest\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\",\"version\":1}","profile_digest":"eb287a75294713a92759b304008539d831db2566d7416621bc7ae6b8c0e29bb1"},{"name":"raw_video_source_only","profile":{"version":1,"generation":"10000000-0000-4000-8000-000000000001","source_backend_generation":"10000000-0000-4000-8000-000000000002","source_backend_config_digest":"7777777777777777777777777777777777777777777777777777777777777777","destination_backend_generation":"10000000-0000-4000-8000-000000000003","destination_backend_config_digest":"8888888888888888888888888888888888888888888888888888888888888888","protocol_artifact_digest":"b4c50d2dda319599a9e9968582e077d52c0cf8b391799d10724aa1dce1f3dc53","copy_adapter_digest":"9999999999999999999999999999999999999999999999999999999999999999","verification_adapter_digest":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","cohort_limits":{"max_ordinals":8,"max_unique_objects":10,"max_unique_bytes":28625792,"content_type_pairs":[{"kind":"video","source_content_type":"video/mp4","prepared_content_type":null}],"alias_policy":"same_ordinal_exact_bytes_only","video_policy":"source_only"},"phase_ms":{"admission":10000,"copy":25000,"verification_claim":5000,"verification":15000,"verification_settlement":5000,"transfer":5000,"reconciliation":10000,"protocol_margin":5000},"total_ms":80000,"execution_model":"sequential_whole_cohort"},"profile_canonical":"{\"cohort_limits\":{\"alias_policy\":\"same_ordinal_exact_bytes_only\",\"content_type_pairs\":[{\"kind\":\"video\",\"prepared_content_type\":null,\"source_content_type\":\"video/mp4\"}],\"max_ordinals\":8,\"max_unique_bytes\":28625792,\"max_unique_objects\":10,\"video_policy\":\"source_only\"},\"copy_adapter_digest\":\"9999999999999999999999999999999999999999999999999999999999999999\",\"destination_backend_config_digest\":\"8888888888888888888888888888888888888888888888888888888888888888\",\"destination_backend_generation\":\"10000000-0000-4000-8000-000000000003\",\"execution_model\":\"sequential_whole_cohort\",\"generation\":\"10000000-0000-4000-8000-000000000001\",\"phase_ms\":{\"admission\":10000,\"copy\":25000,\"protocol_margin\":5000,\"reconciliation\":10000,\"transfer\":5000,\"verification\":15000,\"verification_claim\":5000,\"verification_settlement\":5000},\"protocol_artifact_digest\":\"b4c50d2dda319599a9e9968582e077d52c0cf8b391799d10724aa1dce1f3dc53\",\"source_backend_config_digest\":\"7777777777777777777777777777777777777777777777777777777777777777\",\"source_backend_generation\":\"10000000-0000-4000-8000-000000000002\",\"total_ms\":80000,\"verification_adapter_digest\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\",\"version\":1}","profile_digest":"9caa8b7edcd6f8cc7bc805805108a35d4aaa48d25ab0dfe43ba584b66a405b6a"}],"budget":{"anchor_ms":1000000,"expires_at_ms":1300000,"preparation_wall_ms":20000,"cutoffs":{"admission":1010000,"copy":1035000,"verification_claim":1040000,"verification":1055000,"verification_settlement":1060000,"transfer":1065000,"reconciliation":1075000,"protocol_margin":1080000},"issue_required_ms":145000}}$vectors$::JSONB v;
CREATE TEMP TABLE handoff_profile AS SELECT (v->'valid'->0->>'profile_canonical') p,v->>'protocol_canonical' a FROM handoff_vectors;
SELECT extensions.is(internal.parse_initial_handoff_shape('protocol_artifact',v->>'protocol_canonical'),v->'protocol_artifact','closed protocol vector') FROM handoff_vectors;
SELECT extensions.is(internal.initial_handoff_digest('protocol_artifact',v->>'protocol_canonical'),v->>'protocol_digest','protocol digest parity') FROM handoff_vectors;
SELECT extensions.is(internal.parse_initial_handoff_profile(item->>'profile_canonical',v->>'protocol_canonical'),item->'profile','profile parse '||(item->>'name')) FROM handoff_vectors CROSS JOIN LATERAL jsonb_array_elements(v->'valid') item;
SELECT extensions.is(internal.initial_handoff_digest('profile',item->>'profile_canonical'),item->>'profile_digest','profile digest '||(item->>'name')) FROM handoff_vectors CROSS JOIN LATERAL jsonb_array_elements(v->'valid') item;
SELECT extensions.is(internal.initial_handoff_phase_cutoffs(p,a,1000000,1300000),(SELECT v#>'{budget,cutoffs}' FROM handoff_vectors),'all cumulative cutoffs') FROM handoff_profile;
SELECT extensions.lives_ok(format('SELECT internal.assert_initial_handoff_issue_budget(%L,%L,1000000,1145001,20000)',p,a),'one millisecond above complete issue budget') FROM handoff_profile;
SELECT extensions.throws_ok(format('SELECT internal.assert_initial_handoff_issue_budget(%L,%L,1000000,1145000,20000)',p,a),'55000','initial_analysis_handoff_budget_unavailable','issue equality rejected') FROM handoff_profile;
SELECT extensions.throws_ok(format('SELECT internal.assert_initial_handoff_issue_budget(%L,%L,1000000,1100001,20000)',p,a),'55000','initial_analysis_handoff_budget_unavailable','old future reserve insufficient') FROM handoff_profile;
SELECT extensions.throws_ok(format('SELECT internal.initial_handoff_phase_cutoffs(%L,%L,1000000,1080000)',p,a),'55000','initial_analysis_handoff_budget_unavailable','admission equality rejected') FROM handoff_profile;
SELECT extensions.is(internal.initial_handoff_phase_cutoffs(p,a,9007199254660990,9007199254740991)->>'protocol_margin','9007199254740990','safe integer edge preserves final millisecond') FROM handoff_profile;
SELECT extensions.lives_ok(format('SELECT internal.assert_initial_handoff_issue_budget(%L,%L,9007199254595990,9007199254740991,20000)',p,a),'safe issue edge') FROM handoff_profile;
SELECT extensions.throws_ok(format('SELECT internal.assert_initial_handoff_issue_budget(%L,%L,9007199254595991,9007199254740991,20000)',p,a),'55000','initial_analysis_handoff_budget_unavailable','safe issue equality') FROM handoff_profile;
-- Invalid closed metadata and semantic pairs cannot pass as qualification.
CREATE TEMP TABLE bad_profiles AS
SELECT p::JSONB-'generation' value,'missing key' label FROM handoff_profile UNION ALL
SELECT p::JSONB||'{"unexpected":1}', 'extra key' FROM handoff_profile UNION ALL
SELECT jsonb_set(p::JSONB,'{protocol_artifact_digest}',to_jsonb(repeat('0',64))), 'wrong artifact' FROM handoff_profile UNION ALL
SELECT jsonb_set(p::JSONB,'{cohort_limits,content_type_pairs}','[]'), 'empty pairs' FROM handoff_profile UNION ALL
SELECT jsonb_set(p::JSONB,'{cohort_limits,content_type_pairs}',jsonb_build_array(p::JSONB#>'{cohort_limits,content_type_pairs,0}',p::JSONB#>'{cohort_limits,content_type_pairs,0}')), 'duplicate pairs' FROM handoff_profile UNION ALL
SELECT jsonb_set(p::JSONB,'{cohort_limits,max_unique_objects}','1'), 'objects below ordinals' FROM handoff_profile UNION ALL
SELECT jsonb_set(p::JSONB,'{cohort_limits,max_unique_bytes}','28625793'), 'byte cap' FROM handoff_profile UNION ALL
SELECT jsonb_set(p::JSONB,'{cohort_limits,content_type_pairs}', '[{"kind":"image","source_content_type":"image/png","prepared_content_type":"image/jpeg"}]'), 'image conversion' FROM handoff_profile UNION ALL
SELECT jsonb_set(p::JSONB,'{cohort_limits,content_type_pairs}', '[{"kind":"audio","source_content_type":"audio/mp4","prepared_content_type":"audio/wav"}]'), 'unqualified audio' FROM handoff_profile UNION ALL
SELECT jsonb_set(p::JSONB,'{cohort_limits,content_type_pairs}', '[{"kind":"video","source_content_type":"video/mp4","prepared_content_type":"video/mp4"}]'), 'prepared video' FROM handoff_profile UNION ALL
SELECT jsonb_set(p::JSONB,'{phase_ms,copy}','0'), 'zero phase' FROM handoff_profile UNION ALL
SELECT jsonb_set(p::JSONB,'{phase_ms,copy}','1.5'), 'fractional phase' FROM handoff_profile UNION ALL
SELECT jsonb_set(p::JSONB,'{total_ms}','80001'), 'phase sum mismatch' FROM handoff_profile UNION ALL
SELECT jsonb_set(p::JSONB,'{total_ms}','9007199254740992'), 'unsafe total' FROM handoff_profile;
SELECT extensions.throws_ok(format('SELECT internal.parse_initial_handoff_profile(%L,%L)',internal.initial_canonical(value),a),'22023','initial_analysis_input_invalid',label) FROM bad_profiles CROSS JOIN handoff_profile WHERE label NOT IN ('fractional phase','unsafe total');
SELECT extensions.throws_ok(format('SELECT internal.parse_initial_handoff_profile(%L,%L)',value::TEXT,a),'22023','initial_analysis_input_invalid',label) FROM bad_profiles CROSS JOIN handoff_profile WHERE label IN ('fractional phase','unsafe total');
SELECT extensions.throws_ok(format('SELECT internal.parse_initial_handoff_profile(%L,%L)',p,internal.initial_canonical(jsonb_set(a::JSONB,'{m1_mapping,schema_version}','1'))),'22023','initial_analysis_input_invalid','component version drift') FROM handoff_profile;
SELECT extensions.throws_ok(format('SELECT internal.parse_initial_handoff_profile(%L,%L)',p,a||E'\n'),'22023','initial_analysis_input_invalid','noncanonical artifact') FROM handoff_profile;
SELECT extensions.throws_ok(format('SELECT internal.parse_initial_handoff_shape(%L,%L)','profile',bad),'22023','initial_analysis_input_invalid','bad canonical profile') FROM handoff_profile CROSS JOIN LATERAL unnest(ARRAY[p||E'\n','{"generation":"duplicate",'||substr(p,2),'null','{',repeat(' ',16385),NULL]) bad;
SELECT extensions.throws_ok(format('SELECT internal.initial_handoff_digest(%L,%L)',domain,p),'22023','initial_analysis_input_invalid','digest domain') FROM handoff_profile CROSS JOIN unnest(ARRAY['arbitrary',NULL]) domain;
SELECT extensions.throws_ok(format('SELECT internal.initial_handoff_digest(%L,%L)','profile',p||E'\n'),'22023','initial_analysis_input_invalid','digest canonical spelling') FROM handoff_profile;
SELECT extensions.throws_ok(format('SELECT internal.assert_initial_handoff_window(%L::NUMERIC,%L::NUMERIC)',n,e),'22023','initial_analysis_input_invalid','invalid time window') FROM (VALUES ('-1','1'),('1','1'),('2','1'),('0','300001'),('1.5','2'),('NaN','4'),('1','Infinity'),('0','9007199254740992'),(NULL,'1'),('1',NULL)) x(n,e);
SELECT extensions.throws_ok(format('SELECT internal.assert_initial_handoff_issue_budget(%L,%L,1000000,1300000,%L::NUMERIC)',p,a,w),'22023','initial_analysis_input_invalid','invalid wall') FROM handoff_profile CROSS JOIN unnest(ARRAY['0','-1','0.5','NaN','Infinity','300001',NULL]) w;
SELECT extensions.ok(NOT has_function_privilege(r,s,'EXECUTE'),'private invoker '||r||s) FROM unnest(ARRAY['anon','authenticated','service_role']) r CROSS JOIN unnest(ARRAY[
 'internal.initial_handoff_schema()', 'internal.initial_handoff_digest(text,text)', 'internal.parse_initial_handoff_shape(text,text)', 'internal.parse_initial_handoff_profile(text,text)', 'internal.assert_initial_handoff_window(numeric,numeric)', 'internal.assert_initial_handoff_issue_budget(text,text,numeric,numeric,numeric)', 'internal.initial_handoff_phase_cutoffs(text,text,numeric,numeric)']) s;
SELECT extensions.is((SELECT count(*)::INTEGER FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='internal' AND p.proname IN ('initial_handoff_schema','initial_handoff_digest','parse_initial_handoff_shape','parse_initial_handoff_profile','assert_initial_handoff_window','assert_initial_handoff_issue_budget','initial_handoff_phase_cutoffs') AND (p.prosecdef OR NOT ('search_path=""'=ANY(p.proconfig)))),0,'all invoker helpers have empty search path');
SELECT extensions.is((SELECT initial_analysis_lifecycle_enabled FROM internal.initial_analysis_rollout),FALSE,'activation stays false');
SELECT extensions.is((SELECT count(*)::INTEGER FROM internal.initial_preparation_current_selection),0,'no active selector');
-- NUMERIC has no signed-zero state; canonical wire spelling still rejects -0.
SELECT extensions.lives_ok('SELECT internal.assert_initial_handoff_window(0,1)','typed numeric zero accepted');
SELECT extensions.throws_ok($q$SELECT internal.initial_handoff_digest('profile','-0')$q$,'22023','initial_analysis_input_invalid','canonical signed zero rejected');
SELECT * FROM extensions.finish();
ROLLBACK;
